/* ---------------- kum dolan logo (site entegrasyonu) ---------------- */
/* Kaynak: kum-logo-duzeltilmis.html demosu. Boyut sabit 320x85 kutuya
   sığacak şekilde (en-boy oranı korunarak) ölçekleniyor. Tema (gündüz/gece)
   sitenin kendi koyu/açık tema anahtarına bağlı — ayrı bir gündüz/gece
   butonu yok. */
(function(){

  const FILL_DURATION   = 30000;
  const GRAIN_COUNT     = 5200;
  const SAND_COLOR_DAY   = '#e0a72e';
  const SAND_COLOR_NIGHT = '#f5f5f5';
  const EMPTY_OPACITY    = 0.14;
  const BUCKET_WIDTH     = 2;
  const SPAWN_PER_FRAME  = 5;
  const BOX_W = 320, BOX_H = 85;

    const LETTER_SRC = "data:image/png;base64,";
    const BLUE_SRC   = "data:image/png;base64,";

  let W, H, letterData, grains, particles, startTime;
  let bucketSegments;
  let bucketCount;
  let theme = 'night';
  let canvas, ctx;
  let maskCanvas, maskCtx;
  let baslatildi = false;
  let calisiyor = false;
  let sekmeGizli = false;

  function buildSegments(){
    const arr = new Array(bucketCount);
    for (let bi = 0; bi < bucketCount; bi++){
      const x0 = bi * BUCKET_WIDTH;
      const x1 = Math.min(W, x0 + BUCKET_WIDTH);
      const segs = [];
      let curTop = -1;
      for (let y = 0; y < H; y++){
        let opaque = false;
        for (let x = x0; x < x1; x++){
          if (letterData[(y * W + x) * 4 + 3] > 100){ opaque = true; break; }
        }
        if (opaque){
          if (curTop === -1) curTop = y;
        } else if (curTop !== -1){
          segs.push({ top: curTop, bottom: y - 1 });
          curTop = -1;
        }
      }
      if (curTop !== -1) segs.push({ top: curTop, bottom: H - 1 });
      arr[bi] = segs;
    }
    return arr;
  }

  function spawnParticles(progress){
    for (let i = 0; i < SPAWN_PER_FRAME; i++){
      const bi = (Math.random() * bucketCount) | 0;
      const segs = bucketSegments[bi];
      if (!segs || segs.length === 0) continue;
      const seg = segs[(Math.random() * segs.length) | 0];
      const pileTop = pileTopFor(seg, progress);
      if (pileTop <= seg.top + 2) continue;
      particles.push({
        x: bi * BUCKET_WIDTH + BUCKET_WIDTH / 2,
        y: seg.top - 4 - Math.random() * 10,
        bi, seg,
        vy: 3.3 + Math.random() * 2.4,
        r: 0.8 + Math.random() * 0.7,
        alpha: 0.85 + Math.random() * 0.15
      });
    }
  }

  function pileTopFor(seg, progress){
    if (!seg) return H;
    return seg.bottom - Math.min(1, progress * 1.08) * (seg.bottom - seg.top);
  }

  function shadeColor(base, amt){
    const c = base.replace('#','');
    const num = parseInt(c,16);
    let r = (num>>16)+amt, g=((num>>8)&0xff)+amt, b=(num&0xff)+amt;
    r=Math.max(0,Math.min(255,r)); g=Math.max(0,Math.min(255,g)); b=Math.max(0,Math.min(255,b));
    return `rgb(${r},${g},${b})`;
  }

  function drawMaskedLayer(paintFn){
    maskCtx.clearRect(0, 0, W, H);
    paintFn(maskCtx);
    maskCtx.globalCompositeOperation = 'destination-in';
    maskCtx.drawImage(letterImg, 0, 0, W, H);
    maskCtx.globalCompositeOperation = 'source-over';
    ctx.drawImage(maskCanvas, 0, 0, W, H);
  }

  function draw(now){
    if (!canvas || !canvas.isConnected) { calisiyor = false; return; } // sayfa/element kaldırıldıysa dur
    if (sekmeGizli) { calisiyor = false; return; } // sekme arka plandayken çizim yapma, geri gelince yeniden tetiklenir
    const elapsed = now - startTime;
    const progress = Math.min(1, elapsed / FILL_DURATION);

    const sandColor  = theme === 'acik' ? SAND_COLOR_DAY : SAND_COLOR_NIGHT;
    const emptyColor = theme === 'acik' ? `rgba(40,30,10,${EMPTY_OPACITY})` : `rgba(255,255,255,${EMPTY_OPACITY})`;

    ctx.clearRect(0,0,W,H);

    drawMaskedLayer(m => {
      m.fillStyle = emptyColor;
      m.fillRect(0, 0, W, H);
    });

    drawMaskedLayer(m => {
      m.fillStyle = sandColor;
      for (let bi = 0; bi < bucketCount; bi++){
        const segs = bucketSegments[bi];
        for (const seg of segs){
          const pileTop = pileTopFor(seg, progress);
          if (pileTop >= seg.bottom) continue;
          m.fillRect(bi * BUCKET_WIDTH, pileTop, BUCKET_WIDTH + 0.6, seg.bottom - pileTop + 1);
        }
      }
    });

    drawMaskedLayer(m => {
      for (const g of grains){
        if (progress * 1.08 >= g.threshold){
          m.beginPath();
          m.fillStyle = g.shade > 0.5 ? shadeColor(sandColor, -20) : shadeColor(sandColor, 16);
          m.arc(g.x, g.y, g.r, 0, Math.PI*2);
          m.fill();
        }
      }
    });

    if (progress < 1 && Math.random() < 0.95) spawnParticles(progress);

    drawMaskedLayer(m => {
      particles.forEach(p=>{
        m.globalAlpha = p.alpha;
        m.beginPath();
        m.fillStyle = sandColor;
        m.arc(p.x, p.y, p.r, 0, Math.PI*2);
        m.fill();
        m.globalAlpha = 1;
      });
    });

    particles.forEach(p=>{
      const pileTop = pileTopFor(p.seg, progress);
      if (p.y < pileTop) p.y += p.vy;
    });
    particles = particles.filter(p=>{
      const pileTop = pileTopFor(p.seg, progress);
      return p.y < pileTop + 6;
    });

    ctx.drawImage(blueImg, 0, 0, W, H);

    // Dolum tamamlandıysa ve düşen parçacık kalmadıysa döngüyü DURDUR —
    // aksi halde tarayıcı sekmesi arka planda kalıp geri gelindiğinde
    // gereksiz yere sürekli çizim yapmaya devam ederdi (donma hissi).
    if (progress < 1 || particles.length > 0) {
      calisiyor = true;
      requestAnimationFrame(draw);
    } else {
      calisiyor = false; // sabit son kare olarak kalır, tema değişince tekrar tetiklenir
    }
  }

  let letterImg, blueImg;

  function kurulumYap(){
    W = letterImg.naturalWidth;
    H = letterImg.naturalHeight;

    const olcek = Math.min(BOX_W / W, BOX_H / H);
    const dispW = Math.round(W * olcek);
    const dispH = Math.round(H * olcek);
    const dpr = Math.min(window.devicePixelRatio || 1, 2);

    canvas.width  = W * dpr;
    canvas.height = H * dpr;
    canvas.style.width  = dispW + 'px';
    canvas.style.height = dispH + 'px';
    ctx = canvas.getContext('2d');
    ctx.setTransform(dpr,0,0,dpr,0,0);

    maskCanvas = document.createElement('canvas');
    maskCanvas.width = W; maskCanvas.height = H;
    maskCtx = maskCanvas.getContext('2d');

    const off = document.createElement('canvas');
    off.width = W; off.height = H;
    const octx = off.getContext('2d');
    octx.drawImage(letterImg, 0, 0, W, H);
    letterData = octx.getImageData(0, 0, W, H).data;

    bucketCount = Math.ceil(W / BUCKET_WIDTH);
    bucketSegments = buildSegments();

    grains = [];
    let guard = 0;
    while (grains.length < GRAIN_COUNT && guard < GRAIN_COUNT * 40){
      guard++;
      const x = Math.random() * W;
      const y = Math.random() * H;
      const xi = Math.floor(x), yi = Math.floor(y);
      const a = letterData[(yi * W + xi) * 4 + 3];
      if (a > 80){
        const bi = Math.min(bucketCount - 1, Math.floor(x / BUCKET_WIDTH));
        const segs = bucketSegments[bi];
        const seg = segs.find(s => yi >= s.top && yi <= s.bottom);
        if (!seg || seg.bottom === seg.top) continue;
        const threshold = (seg.bottom - y) / (seg.bottom - seg.top);
        grains.push({ x, y, r: 0.55 + Math.random()*0.55, shade: Math.random(), threshold, bi });
      }
    }

    particles = [];
    startTime = performance.now();
    calisiyor = true;
    requestAnimationFrame(draw);
  }

  window.kumLogoBaslat = function(){
    if (baslatildi) return;
    canvas = document.getElementById('kumLogoCanvas');
    if (!canvas) return;
    baslatildi = true;
    letterImg = new Image();
    blueImg = new Image();
    let loaded = 0;
    function onLoad(){ loaded++; if (loaded === 2) kurulumYap(); }
    letterImg.onload = onLoad;
    blueImg.onload = onLoad;
    letterImg.src = LETTER_SRC;
    blueImg.src = BLUE_SRC;
  };

  window.kumLogoTemaGuncelle = function(yeniTema){
    theme = yeniTema;
    // Animasyon tamamlanıp durduysa, yeni rengi yansıtmak için tek bir kare
    // daha çizdirip tekrar durduruyoruz — sürekli döngü açmaya gerek yok.
    if (!calisiyor && canvas && ctx) {
      calisiyor = true;
      requestAnimationFrame(draw);
    }
  };

  // Sekme arka plana alınıp geri geldiğinde tarayıcının biriken kareleri
  // aniden "telafi etmeye" çalışması donma hissi yaratıyordu. Sekme
  // gizliyken döngüyü tamamen durdurup, geri gelince kaldığı ilerlemeden
  // (zaman damgasını kaydırarak) devam ettiriyoruz.
  let gizlenmeAni = 0;
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
      sekmeGizli = true;
      gizlenmeAni = performance.now();
    } else {
      sekmeGizli = false;
      if (gizlenmeAni && startTime) {
        startTime += (performance.now() - gizlenmeAni); // geçen "gizli" süreyi say dışı bırak
      }
      if (!calisiyor && canvas && ctx) {
        calisiyor = true;
        requestAnimationFrame(draw);
      }
    }
  });

})();
